from pathlib import Path
import re, json, html
from urllib.parse import quote

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'sergiomissao-site'
OUT.mkdir(exist_ok=True)
E = html.escape
BASE = 'https://sergiomissao.com.br'
pages = {}

def write(path, text):
    p = OUT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')

def wa(service):
    return 'https://wa.me/5511916556521?text=' + quote('Olá! Gostaria de conversar sobre ' + service + '. Vim pelo site sergiomissao.com.br.')

def cta(service, label='Solicitar proposta'):
    return '<a class="button" href="'+E(wa(service))+'">'+E(label)+'</a>'

def link(url, label, cls='text-link'):
    return f'<a class="{cls}" href="{E(url)}">{E(label)}</a>'

def ul(items):
    return '<ul>'+''.join('<li>'+E(x)+'</li>' for x in items)+'</ul>'

def section(title, content, id=''):
    return f'<section class="section"'+(f' id="{id}"' if id else '')+f'><div class="wrap"><h2>{E(title)}</h2>{content}</div></section>'

def hero(tag, title, intro, action='', img=''):
    return '<section class="page-hero"><div class="wrap hero-grid"><div><p class="eyebrow">'+E(tag)+'</p><h1>'+E(title)+'</h1><p class="lead">'+E(intro)+'</p><div class="actions">'+action+'</div></div>'+img+'</div></section>'

def image(src, alt, cls='', eager=False):
    return f'<img class="{cls}" src="/{src}" alt="{E(alt)}" loading="'+('eager' if eager else 'lazy')+'" decoding="async">'

nav = [('palestras','Palestras'),('treinamentos','Treinamentos'),('consultoria','Consultoria'),('mentoria','Mentoria'),('apresentacoes','Apresentações'),('cooperativas','Cooperativas'),('organizadores','Organizadores'),('sobre','Sobre'),('artigos','Artigos'),('contato','Contato')]
def page(path, title, desc, body):
    url = BASE + ('/'+path+'/' if path else '/')
    menu = ''.join(f'<a href="/{slug}/"'+(' aria-current="page"' if path==slug else '')+f'>{name}</a>' for slug,name in nav)
    schema = {'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url,'inLanguage':'pt-BR'}
    markup = f'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | Sérgio Missão</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{url}"><link rel="icon" href="/logo-sm.png"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta property="og:site_name" content="Sérgio Missão"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/foto-palco.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body>
<a class="skip" href="#conteudo">Pular para o conteúdo</a><header class="site-header"><div class="wrap topbar"><a class="brand" href="/">{image('logo-sm.png','', 'logo',True)}<span>Sérgio Missão<small>#NaMissão</small></span></a><a class="header-contact" href="/contato/">Solicitar proposta</a><button id="menu-button" aria-expanded="false" aria-controls="nav">Menu <span aria-hidden="true">☰</span></button></div><nav id="nav" aria-label="Principal" class="wrap">{menu}</nav></header>
<main id="conteudo">{body}</main><footer><div class="wrap footer-grid"><div><a class="brand" href="/">Sérgio Missão</a><p>Liderança, comunicação e desenvolvimento de pessoas.</p><p>Profissionais, empresas e cooperativas.</p></div><div><strong>Vamos conversar</strong><a href="{E(wa('uma proposta'))}">WhatsApp: +55 11 91655-6521</a><a href="mailto:contato@sergiomissao.com.br">contato@sergiomissao.com.br</a><a href="https://www.linkedin.com/in/missao">LinkedIn</a><a href="https://www.instagram.com/sergio.missao">Instagram</a></div><div><strong>Continue por aqui</strong><a href="/organizadores/">Para organizadores</a><a href="/artigos/">Artigos e newsletter</a><a href="/posts/">Posts</a><a href="/quem-voce-contrataria/">Quem você contrataria?</a></div></div><p class="wrap copyright">© <span id="ano">2026</span> Sérgio Missão · #NaMissão</p></footer></body></html>'''
    write((path+'/' if path else '')+'index.html',markup)
    pages[path] = title

